function updateBoard(board, click) {
  const rows = board.length;
  const cols = board[0].length;
  const [clickRow, clickCol] = click;
  if (board[clickRow][clickCol] === 'M') {
    board[clickRow][clickCol] = 'X';
    return board;
  }

  const stack = [[clickRow, clickCol]];
  while (stack.length > 0) {
    const [row, col] = stack.pop();
    if (board[row][col] !== 'E') continue;
    let mines = 0;
    const neighbors = [];
    for (let dr = -1; dr <= 1; dr++) {
      for (let dc = -1; dc <= 1; dc++) {
        const r = row + dr;
        const c = col + dc;
        if ((dr === 0 && dc === 0) || r < 0 || r >= rows || c < 0 || c >= cols) continue;
        if (board[r][c] === 'M') mines++;
        neighbors.push([r, c]);
      }
    }
    if (mines > 0) {
      board[row][col] = String(mines);
    } else {
      board[row][col] = 'B';
      for (const [r, c] of neighbors) {
        if (board[r][c] === 'E') stack.push([r, c]);
      }
    }
  }
  return board;
}

